function scrollToElement(t){const e=document.getElementById(t);if(!e)return;const o=window.innerWidth<992?0:92,n=e.getBoundingClientRect().top+window.pageYOffset-o;window.scrollTo({top:n,behavior:"smooth"}),document.querySelectorAll("#artistTabs .nav-link").forEach(t=>t.classList.remove("active"));const s=document.querySelector(`#artistTabs button[data-scroll-target="${t}"]`);s&&s.classList.add("active")}const tabs=document.querySelectorAll("#artistTabs .nav-link"),sections=document.querySelectorAll(".tab-section"),offset=120;window.addEventListener("scroll",()=>{let t=null;sections.forEach(e=>{const o=e.getBoundingClientRect();o.top<=120&&o.bottom>120&&(t=e.id)}),t&&tabs.forEach(e=>{e.classList.toggle("active",e.dataset.target===t)})}),document.addEventListener("click",function(t){var e=t.target&&t.target.closest?t.target.closest("[data-scroll-target]"):null;e&&scrollToElement(e.getAttribute("data-scroll-target"))});